import json,pathlib,zipfile,html
from PIL import Image,ImageDraw
root=pathlib.Path(__file__).resolve().parents[2];d=root/'docs/clinical-deep-dives';p=root/'docs/pulse-load'
r=json.loads((d/'verification.json').read_text());pulse=json.loads((p/'verification.json').read_text());capture=json.loads((d/'capture-report.json').read_text())
assert r['pass'] and pulse['pass'] and capture['webgl2'] and not capture['errors']
outcomes={'still':'Calf pump and flow switch between motion and pooling','form-clot':'Camera frames a growing layered clot in the calf vein','release-clot':'Clot travels and camera follows the real venous route','large':'Main-split clot, wider lung dimming and right-heart strain','anticoagulant':'Growth stops; slow endogenous clot clearance is shown','thrombolytic':'Rapid clot shrinkage and recovering perfusion','filter':'A visible IVC filter catches the traveling clot','compare':'Switches between single and side-by-side anatomy','normal':'Restores normal flow or the open airway','next':'Caption and scene advance together','previous':'Caption and scene move back together','speed':'Flow rate and readable motion markers change','clot-site':'Clot moves to the chosen source-vein location','timeline':'Clot and camera seek together','depth-detailed':'Anatomy context changes and Coming next appears','depth-clinical':'Body context changes and Coming next appears','return-basics':'Restores the active example and its camera frame','play':'Freezes/resumes the shared clock; paused illustration dims','theme':'Canvas background and material palette change','reset':'Returns to intact anatomy, normal flow and default framing','sources':'Source disclosure and anatomy context framing change','sound':'Wheeze audio toggle and visible wave marker','rescue':'Puff travels down the trachea; muscle relaxes','controller':'Lining swelling falls; later triggers have less effect','montelukast':'Inflammation target highlights with leukotriene explanation'}
def outcome(control):
 if control.startswith('trigger-'):return 'Trigger starts muscle tightening, lining swelling, mucus and reduced flow'
 if control.startswith('zoom-'):return 'Camera frames the selected real anatomy or representative airway section'
 return outcomes.get(control,'Scene state changes')
lines=['# RxAtlas clinical deep dives — verification','', 'Software WebGL 2 was available. These are browser-rendered screenshots and recordings, not generated mockups. All medical copy remains pending human review.','', '## Scope','', '- Five-stop aortic pulse slider: heartbeat, ECG, optional sound, pulse rings, wall/flap movement, growth, flow and gauges share one clock. Low and Very low stop tear growth. Sustained Very high offers rupture playback; it never starts it automatically.','- DVT/PE: calf pump, stasis, source-derived venous journey, pulmonary obstruction, anticoagulant clearance, thrombolysis, IVC filter and comparison.','- Asthma: source airway tree and representative airway section, triggers, rescue, controller, comparison and optional sound.','- New catalog entries have static molecular assets or explicit mixture notes. No dosing.','', '## Control audit','', '| Topic | Control | Visible result | Changed canvas pixels | Result |','|---|---|---|---:|---|']
for c in r['checks']: lines.append(f"| {c['topic']} | {c['control']} {c.get('value','')} | {outcome(c['control'])} | {c['pixelFraction']:.3%} | {'PASS' if c['pass'] else 'FAIL'} |")
lines+=['','Canvas threshold: more than 0.05% of sampled pixels change by over 10 channel levels. Unavailable controls are disabled.','', '## Aortic pulse stops','', '| Stop | Animation cycles/s | Tear growth setting | Canvas change |','|---|---:|---:|---:|']
names={0:'Very low',.25:'Low',.5:'Normal',.75:'High',1:'Very high'}
for s in pulse['stops']:
 if not s['mobile']: lines.append(f"| {names[s['value']]} | {s['frequency']:.4g} | {s['growthRate']:.4g} | {str(round(s['pixelFraction']*100,2))+'%' if s['pixelFraction'] is not None else 'baseline'} |")
lines+=['','These are internal animation parameters, not clinical vital signs or a validated prediction of rupture. The interface is qualitative. Low-end growth was asserted to be zero, phase advanced, and frequencies matched the configured stop values.','', '## Performance','', '| Scene | Software-rendered FPS |','|---|---:|']
for source,prefix in [(r['fps'],'Desktop'),(capture['fps'],'Mobile emulation'),(pulse['fps'],'Aortic Very high')]:
 for key,value in source.items():lines.append(f'| {prefix}: {key} | {value:.2f} |')
lines+=['','All clinical controls use useClinicalStore.act; reset uses the same store’s reset action, URL restoration uses restore, and tick advances the shared scene clock. URL navigation now increments the camera revision. The airway screenshot checks also require visible geometry, not merely a pixel difference.\n\nSwiftShader measurements are not physical phone/GPU results. Smoothness on a real laptop and phone still needs a device check; no 60 FPS claim is made.','', '## Anatomy and content provenance','', 'The main body GLB and molecule renderer are unchanged. New scenes extract registered BodyParts3D meshes and centerlines without per-part centering. Smooth vessel joins, valve leaflets, clot, airway layers and blood flow are labeled teaching schematics. Chamber transit is an illustrative path through the real chamber geometry. The representative airway wall layers are not segmented histology.','', 'BodyParts3D © DBCLS, CC BY 4.0 (license updated 2025-02-27); releases 4.0 and 4.3. See CREDITS.md.','', 'Sources: ASH 2020 VTE guidelines; CHEST 2021 antithrombotic guideline; GINA 2026 strategy report; NAEPP 2020 focused updates; ACC/AHA 2022 aortic guideline. All new text is pending review.','', 'Molecules: PubChem static structures for the requested small molecules; alteplase uses PDB 1RTF, a representative catalytic domain, not the complete protein. Heparin and enoxaparin are mixtures and intentionally have no single-molecule structure. The catalog-wide availability notes also include polyethylene glycol 3350, a polymer distribution. Existing 2D-only records are linaclotide, mupirocin, nitroprusside, nystatin, tenofovir disoproxil and velpatasvir. No unexpected structure gap remains among the newly requested drugs.','', '## Evidence','']
for v in capture['videos']:lines.append(f"- [{v['name']}.gif]({v['name']}.gif) — {v['frames']} captured frames")
(d/'README.md').write_text('\n'.join(lines)+'\n')
imgs=[d/'dvt-pe-form-clot.png',d/'dvt-pe-thrombolytic.png',d/'asthma-trigger-pollen.png',d/'asthma-compare-on.png',p/'desktop-0.png',p/'desktop-1.png']
montage=Image.new('RGB',(1600,1800),'white');draw=ImageDraw.Draw(montage)
for i,file in enumerate(imgs):
 assert file.exists(),file
 im=Image.open(file).convert('RGB');im.thumbnail((800,565));x=(i%2)*800;y=(i//2)*600;montage.paste(im,(x,y+30));draw.text((x+10,y+7),file.stem,fill='black')
montage.save(d/'verification-montage.jpg',quality=93)
page='<meta charset="utf-8"><title>RxAtlas clinical verification</title><style>body{font:16px system-ui;max-width:1200px;margin:40px auto}img{max-width:100%}figure{margin:24px 0}</style><h1>RxAtlas — clinical deep dives</h1><p>Actual software-WebGL captures. Medical content pending review.</p>'
for file in [d/'verification-montage.jpg']+[d/(v['name']+'.gif') for v in capture['videos']]:page+=f'<figure><figcaption>{html.escape(file.stem)}</figcaption><img src="{file.name}"></figure>'
(d/'gallery.html').write_text(page)
with zipfile.ZipFile(d/'clinical-evidence.zip','w',zipfile.ZIP_DEFLATED) as z:
 selected=set(capture['screenshots'])|{v['name']+'.gif' for v in capture['videos']}|{'verification.json','capture-report.json','mobile-label-verification.json','README.md','gallery.html','verification-montage.jpg'}
 for name in sorted(selected):z.write(d/name,'clinical-deep-dives/'+name)
 for name in ['verification.json','normal-verification.json','normal-high.png','desktop-0.png','desktop-0.25.png','desktop-0.5.png','desktop-0.75.png','desktop-1.png','mobile-1.png']:z.write(p/name,'pulse-load/'+name)
 z.write(root/'CREDITS.md','CREDITS.md')
print('Clinical report and evidence archive ready')
